/**
 * @summary Get computed tax summary for a client
 */
export const getGetTaxSummaryUrl = (
  clientId: number,
  params?: GetTaxSummaryParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/clients/${clientId}/tax-summary?${stringifiedParams}`
    : `/api/clients/${clientId}/tax-summary`;
};

export const getTaxSummary = async (
  clientId: number,
  params?: GetTaxSummaryParams,
  options?: RequestInit,
): Promise<TaxSummary> => {
  return customFetch<TaxSummary>(getGetTaxSummaryUrl(clientId, params), {
    ...options,
    method: "GET",
  });
};

export const getGetTaxSummaryQueryKey = (
  clientId: number,
  params?: GetTaxSummaryParams,
) => {
  return [
    `/api/clients/${clientId}/tax-summary`,
    ...(params ? [params] : []),
  ] as const;
};

export const getGetTaxSummaryQueryOptions = <
  TData = Awaited<ReturnType<typeof getTaxSummary>>,
  TError = ErrorType<unknown>,
>(
  clientId: number,
  params?: GetTaxSummaryParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getTaxSummary>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetTaxSummaryQueryKey(clientId, params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getTaxSummary>>> = ({
    signal,
  }) => getTaxSummary(clientId, params, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!clientId,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getTaxSummary>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetTaxSummaryQueryResult = NonNullable<
  Awaited<ReturnType<typeof getTaxSummary>>
>;
export type GetTaxSummaryQueryError = ErrorType<unknown>;

/**
 * @summary Get computed tax summary for a client
 */

export function useGetTaxSummary<
  TData = Awaited<ReturnType<typeof getTaxSummary>>,
  TError = ErrorType<unknown>,
>(
  clientId: number,
  params?: GetTaxSummaryParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getTaxSummary>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetTaxSummaryQueryOptions(clientId, params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
